  return baked([b(0,.46,0,.7,.65,.8,'#708c69'),b(0,.9,-.15,.65,.48,.58,'#9bad7d'),b(-.19,.93,-.45,.13,.12,.04,'#ecd69b'),b(.19,.93,-.45,.13,.12,.04,'#ecd69b'),b(-.29,.13,.2,.2,.27,.3,'#465b4d'),b(.29,.13,.2,.2,.27,.3,'#465b4d'),b(0,1.2,-.09,.13,.22,.22,'#d9c8a2')]).geometry;
