    this.hero.glider.visible=false;this.dummy=new THREE.Object3D();this.color=new THREE.Color();this.chunks=new Map();this.level=null;this.ground=null;this.time=0;this.zoom=21;this.cameraMode='iso';this.scale=1;this.look=new THREE.Vector3();this.screen=new THREE.Vector3();
