    this.crates.count=CRATE_POS.length;CRATE_POS.forEach(([cx,cz],i)=>this.instance(this.crates,i,cx,0,cz,1,r?.crates.includes(i)?.45:1,1,0,r?.crates.includes(i)?'#89968c':'#ffffff'));this.crates.instanceMatrix.needsUpdate=true;this.crates.instanceColor.needsUpdate=true;
