  metrics(){const p=this.project(this.hero.root.position.x,this.hero.root.position.z,0),top=this.project(this.hero.root.position.x,this.hero.root.position.z,1.45);return{cameraMode:this.cameraMode,cameraType:this.camera.type,viewYaw:this.viewYaw,heroVisible:this.hero.root.visible,width:this.renderer.domElement.width,height:this.renderer.domElement.height,drawCalls:this.renderer.info.render.calls,triangles:this.renderer.info.render.triangles,avatarPixels:Math.abs(p.y-top.y),avatarScreenFraction:Math.abs(p.y-top.y)/innerHeight};}
